events=[]
class Box:
 def run(**kw):events.append('body')
try:Box().run(value=3)
except TypeError:print('arity',events)

class Box:
 def run(self,**kw):return kw
try:Box().run(self=3)
except TypeError:print('duplicate')
class Other:
 def run(self,/,**kw):return kw
print(Other().run(self=3))

class Box:
 def leaf(self,left,*items,right=2,**kw):return left,items,right,kw
 def run(self):return self.leaf(1,3,4,right=5,label=6)
print(Box().run())

events=[]
class Key:
 def __hash__(self):return hash('x')
 def __eq__(self,other):
  events.append(other)
  Box.run.__kwdefaults__={'x':99,'y':100}
  return other=='x'
class Box:
 def run(self,*,x,y):return x,y
Box.run.__kwdefaults__={Key():7,'y':8}
method=Box().run
print(method(),method(),events)
